export const GLOSSARY_SHARD = Object.freeze({"altcoin":{"slug":"altcoin","cat":"basics","en":"Altcoin","contentLocale":"vi","term":"Altcoin","aka":["alt","đồng coin thay thế","coin rác"],"short":"Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết.","body":[["Chữ altcoin ghép từ alternative coin, nghĩa là đồng thay thế ",["Bitcoin","bitcoin"],". Nhóm này rất rộng: có ",["blockchain lớp 1","layer-1"]," như ",["Ethereum","ethereum"],", Solana; token của ứng dụng ",["DeFi","defi"],"; ",["stablecoin","stablecoin"],"; ",["memecoin","memecoin"],"; token sàn như BNB. Một số người không xếp stablecoin vào altcoin vì chúng không nhằm biến động giá."],"Altcoin thường biến động mạnh hơn BTC theo cả hai chiều. Vốn hóa nhỏ và thanh khoản mỏng khiến một lệnh lớn có thể đẩy giá đi xa, và nhiều đồng giảm sâu rồi không bao giờ hồi lại. Trong giai đoạn thị trường mà altcoin tăng mạnh hơn BTC, cộng đồng hay gọi là mùa altcoin (altseason).","Trước khi mua, hãy xem vốn hóa, nguồn cung lưu hành, lịch mở khóa token, khối lượng giao dịch và sàn nào niêm yết. Cùng một altcoin có thể có thanh khoản rất khác nhau giữa các sàn."],"example":"Giả sử bạn chia 1.000 USDT: 500 USDT vào BTC và 500 USDT vào một altcoin nhỏ. Trong một đợt điều chỉnh, BTC giảm 15% còn altcoin giảm 45%. Phần BTC còn 425 USDT, phần altcoin còn 275 USDT, tổng còn 700 USDT. Để phần altcoin quay lại 500 USDT, giá của nó phải tăng khoảng 82% từ đáy, chứ không phải chỉ 45%.","mistakes":["Thấy giá một altcoin chỉ 0,01 USDT rồi nghĩ nó rẻ hơn BTC, trong khi điều quan trọng là vốn hóa và tổng cung.","Dồn hết vốn vào một altcoin chỉ vì thấy nó đang tăng mạnh trên mạng xã hội.","Bỏ qua lịch mở khóa token, rồi bị bất ngờ khi nguồn cung mới đổ ra thị trường."],"faq":[{"q":"Altseason là gì?","a":"Altseason (mùa altcoin) là giai đoạn nhiều altcoin tăng mạnh hơn Bitcoin trong cùng thời gian. Không có định nghĩa chính thức hay lịch cố định cho giai đoạn này."},{"q":"Ethereum có phải altcoin không?","a":"Theo nghĩa rộng thì có, vì ETH không phải Bitcoin. Tuy nhiên nhiều người tách ETH ra riêng vì quy mô và vai trò nền tảng của nó."}],"title":"Altcoin là gì? Ý nghĩa và rủi ro cần biết","description":"Altcoin là gì, gồm những loại nào, vì sao biến động mạnh hơn Bitcoin và cần kiểm tra gì trước khi mua.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng."],["memecoin","Memecoin (meme coin)","Memecoin là đồng tiền mã hóa lấy cảm hứng từ meme, trò đùa hay văn hóa mạng, giá trị chủ yếu đến từ cộng đồng và sự chú ý thay vì sản phẩm hay dòng tiền thực."],["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."],["token-listing","Niêm yết token (listing)","Niêm yết token là việc một sàn giao dịch chính thức thêm một token vào danh sách để người dùng có thể nạp, rút và giao dịch với các cặp nhất định."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":"/coins","cta":false},"layer-2":{"slug":"layer-2","cat":"basics","en":"Layer 2 (L2)","contentLocale":"vi","term":"Layer 2 (L2, giải pháp lớp 2)","aka":["L2","giải pháp lớp 2","rollup"],"short":"Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn.","body":[["Phần lớn L2 hiện nay của ",["Ethereum","ethereum"]," là rollup: chúng gom hàng trăm giao dịch thành một gói rồi ghi dữ liệu tóm tắt lên Ethereum. Optimistic rollup như Arbitrum, Optimism, Base giả định giao dịch hợp lệ và cho thời gian khiếu nại; ZK rollup như zkSync, Starknet dùng bằng chứng mật mã để chứng minh tính đúng."],["Với ",["Bitcoin","bitcoin"],", Lightning Network là ví dụ nổi tiếng: các bên mở kênh thanh toán và chuyển qua lại gần như tức thì, chỉ ghi lên chuỗi khi mở hoặc đóng kênh."],["L2 thường dùng ETH làm ",["phí gas","gas-fee"]," nhưng là mạng riêng. Bạn cần chọn đúng mạng trong ví và trên sàn. Rút từ một số optimistic rollup về Ethereum qua cầu chính thức có thể mất khoảng 7 ngày. Mỗi L2 có mức độ phi tập trung và rủi ro khác nhau, ví dụ bộ sắp xếp giao dịch (sequencer) còn do một bên vận hành."]],"example":["Giả sử bạn thực hiện 10 lần swap mỗi tháng. Trên mạng chính Ethereum, mỗi lần tốn khoảng 4 ",["USDT","usdt"]," phí gas, tổng 40 USDT. Trên một L2, mỗi lần khoảng 0,1 USDT, tổng 1 USDT. Bạn tiết kiệm được 39 USDT. Nhưng nếu bạn chuyển 0,5 ETH từ L2 về Ethereum qua cầu chính thức của optimistic rollup, tiền có thể phải chờ khoảng 7 ngày, trừ khi dùng cầu bên thứ ba với phí cao hơn."],"mistakes":["Rút ETH từ sàn qua mạng Arbitrum nhưng ví đang xem mạng Ethereum và tưởng chưa nhận được tiền.","Không giữ ETH trên L2 để trả phí gas.","Nghĩ rằng mọi L2 đều an toàn ngang Ethereum mà không xem sequencer và cơ chế rút tiền."],"faq":[{"q":"Layer 2 có an toàn không?","a":"L2 kế thừa một phần bảo mật của L1 nhưng có thêm rủi ro riêng như lỗi hợp đồng cầu nối hoặc sequencer tập trung. Mức độ an toàn khác nhau giữa các L2."},{"q":"Vì sao rút từ L2 về Ethereum mất 7 ngày?","a":"Với optimistic rollup, cầu chính thức giữ một khoảng thời gian khiếu nại để ai cũng có thể chứng minh giao dịch gian lận. ZK rollup thường rút nhanh hơn."}],"title":"Layer 2 (L2) là gì? Vì sao phí rẻ hơn","description":"Layer 2 là gì, rollup hoạt động ra sao, ví dụ Arbitrum, Optimism, Base, Lightning và lưu ý khi rút tiền qua L2.","related":[["layer-1","Layer 1 (L1, blockchain lớp 1)","Layer 1 (L1) là blockchain nền tảng tự xử lý và xác nhận giao dịch bằng cơ chế đồng thuận riêng, có coin gốc riêng, như Bitcoin, Ethereum, Solana hay BNB Chain."],["gas-fee","Phí gas (Gas fee)","Phí gas là khoản phí bạn trả cho mạng blockchain để xử lý một giao dịch hoặc thao tác với hợp đồng thông minh, tính bằng coin gốc của mạng như ETH trên Ethereum."],["cross-chain-bridge","Cầu nối chuỗi chéo (Cross-chain bridge)","Cầu nối chuỗi chéo là giao thức giúp chuyển tài sản hoặc dữ liệu giữa hai blockchain khác nhau, thường bằng cách khóa tài sản ở chuỗi gốc và phát hành bản đại diện ở chuỗi đích."],["ethereum","Ethereum (ETH)","Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này."],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."]],"lesson":null,"coin":{"slug":"arbitrum","name":"Arbitrum","symbol":"ARB"},"tool":null,"cta":false},"spot-trading":{"slug":"spot-trading","cat":"trading","en":"Spot trading","contentLocale":"vi","term":"Giao dịch spot (Spot trading)","aka":["spot","giao dịch giao ngay","spot trading","thị trường spot"],"short":"Giao dịch spot (spot trading) là mua bán tài sản crypto để nhận ngay quyền sở hữu thật ở giá hiện tại, không dùng hợp đồng và mặc định không có đòn bẩy.","body":[["Khi bạn mua 0,1 ",["ETH","ethereum"]," trên thị trường spot, 0,1 ETH thật sự vào tài khoản của bạn. Bạn có thể giữ, rút về ví, chuyển đi hoặc bán lại bất cứ lúc nào. Khác với ",["hợp đồng tương lai","futures-contract"],", bạn không trả ",["phí funding","funding-rate"]," và không ",["bị thanh lý","liquidation"]," vì giá giảm."],["Spot được khớp theo ",["cặp giao dịch","trading-pair"]," như ",["BTC","bitcoin"],"/USDT hay ETH/USDT, thông qua sổ lệnh. Bạn có thể dùng lệnh thị trường để khớp ngay hoặc lệnh giới hạn để mua bán ở giá mong muốn. Phí spot theo mô hình maker/taker, tùy sàn và cấp tài khoản."],"Rủi ro tối đa khi giao dịch spot không đòn bẩy là mất số tiền đã bỏ ra nếu giá về gần 0. Với người mới, spot là nơi dễ học nhất vì bạn chỉ cần lo giá và phí, không phải tính toán ký quỹ hay giá thanh lý."],"example":"Giả sử ETH ở mức 2.000 USDT và bạn mua 0,5 ETH với 1.000 USDT, phí 0,1% là 1 USDT. Nếu giá giảm 30% xuống 1.400 USDT, phần ETH của bạn trị giá 700 USDT, bạn vẫn giữ nguyên 0,5 ETH và có thể chờ. Cũng với 1.000 USDT nhưng mở long hợp đồng tương lai đòn bẩy 5x (vị thế 5.000 USDT), cú giảm 30% đó sẽ khiến bạn bị thanh lý và mất gần hết ký quỹ.","mistakes":["Nhầm giao dịch spot với giao dịch hợp đồng trong ứng dụng sàn và vô tình dùng đòn bẩy.","Dùng lệnh thị trường với coin thanh khoản thấp và chịu trượt giá lớn.","Quên tính phí giao dịch khi mua bán quá nhiều lần với số tiền nhỏ."],"faq":[{"q":"Giao dịch spot có bị thanh lý không?","a":"Không, nếu bạn không dùng ký quỹ (margin). Giá có giảm sâu thì bạn vẫn giữ đúng số coin đã mua."},{"q":"Spot khác futures thế nào?","a":"Spot là mua bán coin thật, còn futures là hợp đồng theo dõi giá, có đòn bẩy, phí funding và nguy cơ thanh lý."}],"title":"Giao dịch spot là gì? Spot khác futures ra sao","description":"Giao dịch spot là gì, cách mua bán coin thật trên sàn, khác hợp đồng tương lai thế nào và vì sao phù hợp với người mới.","related":[["trading-pair","Cặp giao dịch (Trading pair)","Cặp giao dịch (trading pair) là hai tài sản được mua bán trực tiếp với nhau trên sàn, ví dụ BTC/USDT, trong đó đồng đứng trước là tài sản cơ sở và đồng đứng sau là đồng định giá."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Giao dịch spot đầu tiên: Từ 100 đến 0.002 BTC"},"coin":null,"tool":"/compare","cta":true},"candlestick-chart":{"slug":"candlestick-chart","cat":"trading","en":"Candlestick chart","contentLocale":"vi","term":"Biểu đồ nến (Candlestick chart)","aka":["nến Nhật","biểu đồ nến Nhật","candlestick","nến"],"short":"Biểu đồ nến là loại biểu đồ giá trong đó mỗi cây nến thể hiện giá mở cửa, giá cao nhất, giá thấp nhất và giá đóng cửa của một tài sản trong một khung thời gian.","body":["Mỗi cây nến có thân nến và râu nến. Thân nến nối giá mở cửa với giá đóng cửa. Râu nến phía trên chạm giá cao nhất, râu phía dưới chạm giá thấp nhất trong khung thời gian đó. Nến xanh thường là giá đóng cửa cao hơn giá mở cửa, nến đỏ là ngược lại, dù bạn có thể đổi màu trong cài đặt.","Khung thời gian do bạn chọn: 1 phút, 15 phút, 1 giờ, 4 giờ, 1 ngày hoặc 1 tuần. Cùng một thị trường có thể trông tăng trên khung ngày nhưng giảm trên khung 15 phút, nên luôn xác định rõ khung bạn đang xem.","Râu nến dài cho thấy giá từng chạy xa nhưng bị kéo lại. Thân nến lớn cho thấy một phía chiếm ưu thế rõ. Các mô hình nến chỉ là gợi ý về tâm lý thị trường, không phải tín hiệu chắc chắn."],"example":["Giả sử trên khung 1 giờ, ",["BTC","bitcoin"]," mở cửa ở 64.000 ",["USDT","usdt"],", lên cao nhất 64.900, xuống thấp nhất 63.700 và đóng cửa ở 64.600. Đây là nến xanh vì giá đóng cửa cao hơn giá mở cửa. Thân nến dài 600 USDT, râu trên dài 300 USDT và râu dưới dài 300 USDT. Biên độ cả cây nến là 64.900 - 63.700 = 1.200 USDT."],"mistakes":["Đọc một cây nến riêng lẻ mà không nhìn bối cảnh xu hướng và volume.","Đưa ra quyết định dựa trên cây nến chưa đóng, trong khi hình dạng của nó còn thay đổi.","Quên rằng một số ứng dụng dùng màu khác, ví dụ đỏ là tăng và xanh là giảm."],"faq":[{"q":"Râu nến là gì?","a":"Râu nến là đường mảnh phía trên và phía dưới thân nến, cho biết giá cao nhất và thấp nhất trong khung thời gian của cây nến đó."},{"q":"Nên xem biểu đồ nến khung nào?","a":"Tùy phong cách giao dịch. Người giữ dài hạn thường xem khung ngày hoặc tuần, người lướt sóng ngắn xem khung từ 5 phút đến 4 giờ."}],"title":"Biểu đồ nến là gì? Cách đọc nến Nhật trong crypto","description":"Biểu đồ nến là gì, cách đọc thân nến, râu nến và khung thời gian để hiểu diễn biến giá crypto.","related":[["support-and-resistance","Hỗ trợ và kháng cự (Support và Resistance)","Hỗ trợ và kháng cự là các vùng giá mà trước đây giá thường dừng giảm (hỗ trợ) hoặc dừng tăng (kháng cự), do lực mua hoặc lực bán tập trung ở đó."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["trading-volume","Khối lượng giao dịch (Volume)","Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ."],["all-time-high","Đỉnh lịch sử (All-time high - ATH)","Đỉnh lịch sử (all-time high, ATH) là mức giá cao nhất mà một tài sản từng đạt được kể từ khi bắt đầu giao dịch, thường được tính theo một đồng tiền định giá như USD hoặc USDT."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"Một cây nến: bốn điều nó thực sự nói cho bạn là gì?"},"coin":null,"tool":null,"cta":false},"last-price":{"slug":"last-price","cat":"derivatives","en":"Last traded price","contentLocale":"vi","term":"Giá giao dịch cuối (Last price)","aka":["last price","giá khớp gần nhất","giá cuối"],"short":"Giá giao dịch cuối (last price) là mức giá của lệnh khớp gần nhất trên sổ lệnh của một sàn, chính là con số giá bạn thấy thay đổi liên tục trên ứng dụng.","body":[["Mỗi khi một lệnh mua và một lệnh bán khớp với nhau, giá giao dịch cuối được cập nhật. ",["Biểu đồ nến","candlestick-chart"]," của sàn được vẽ từ chuỗi giá này. Vì nó chỉ phản ánh giao dịch trên một sàn, nó có thể giật mạnh khi ",["sổ lệnh","order-book"]," mỏng hoặc có lệnh lớn."],["Trong ",["hợp đồng tương lai","futures-contract"],", giá giao dịch cuối khác với ",["giá đánh dấu","mark-price"]," và ",["giá chỉ số","index-price"],". Lãi lỗ đã thực hiện tính theo giá khớp thực tế, còn ",["lãi lỗ chưa thực hiện","unrealized-pnl"]," và thanh lý thường dựa trên giá đánh dấu."],"Khi đặt lệnh dừng như cắt lỗ, nhiều sàn cho bạn chọn kích hoạt theo giá giao dịch cuối hay giá đánh dấu. Chọn giá giao dịch cuối thì lệnh phản ứng nhanh hơn nhưng dễ bị kích hoạt bởi cú giật ngắn."],"example":"Giả sử bạn đặt cắt lỗ cho vị thế long XRP ở 0,58 USDT, kích hoạt theo giá giao dịch cuối. Giá đánh dấu đang 0,60 USDT. Một lệnh bán lớn khiến giá giao dịch cuối chạm 0,578 trong 2 giây rồi hồi về 0,60. Lệnh cắt lỗ của bạn đã kích hoạt và đóng vị thế 1.000 XRP, mất khoảng 22 USDT so với giá 0,60. Nếu chọn kích hoạt theo giá đánh dấu, lệnh có thể đã không chạy.","mistakes":["Không để ý loại giá kích hoạt khi đặt lệnh dừng.","Nghĩ rằng giá giao dịch cuối là giá bạn sẽ được khớp khi đặt lệnh thị trường lớn.","Dùng giá giao dịch cuối để ước tính giá thanh lý."],"faq":[{"q":"Last price là gì?","a":"Là giá khớp lệnh gần nhất trên sàn. Nó cập nhật mỗi khi có giao dịch mới."},{"q":"Nên kích hoạt cắt lỗ theo last price hay mark price?","a":"Last price phản ứng nhanh hơn nhưng dễ bị giật giá kích hoạt. Mark price ổn định hơn nhưng có thể chậm hơn một chút khi giá chạy mạnh."}],"title":"Last price là gì? Giá giao dịch cuối trong crypto","description":"Giá giao dịch cuối (last price) là gì, khác mark price và index price thế nào, và ảnh hưởng gì tới lệnh cắt lỗ.","related":[["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["index-price","Giá chỉ số (Index price)","Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?"},"coin":null,"tool":null,"cta":false},"funding-rate-arbitrage":{"slug":"funding-rate-arbitrage","cat":"derivatives","en":"Funding rate arbitrage","contentLocale":"vi","term":"Arbitrage funding rate (Kinh doanh chênh lệch funding)","aka":["funding arbitrage","arbitrage funding","delta neutral funding","ăn funding"],"short":"Arbitrage funding rate là chiến lược giữ vị thế trung lập về giá, thường là mua spot và short perpetual cùng lượng, để thu khoản funding được trả định kỳ.","body":[["Khi funding dương, phe short nhận tiền từ phe long. Nếu bạn mua 1 ",["BTC","bitcoin"]," spot và short 1 BTC perp, lãi lỗ giá của hai vị thế gần như bù trừ, và bạn nhận funding mỗi kỳ. Khi funding âm, chiến lược đảo lại thường khó hơn vì phải vay coin để bán spot."],"Lợi nhuận phụ thuộc vào mức funding, vốn thay đổi liên tục và có thể đổi dấu. Chi phí gồm phí giao dịch bốn lần (mở và đóng cả hai chân), spread, và chi phí cơ hội của vốn. Một biến thể là short perp trên sàn có funding cao và long perp trên sàn có funding thấp.",["Rủi ro chính là ",["thanh lý","liquidation"]," chân short khi giá tăng mạnh nếu ký quỹ ở tài khoản futures không đủ, dù chân spot đang lãi. Ngoài ra còn rủi ro sàn và rủi ro ",["stablecoin","stablecoin"],"."]],"example":["Giả sử bạn có 20.000 ",["USDT","usdt"],", mua 10.000 USDT ",["ETH","ethereum"]," spot và dùng 10.000 USDT còn lại làm ký quỹ short 10.000 USDT ETH perp (1x). Funding trung bình +0,015% mỗi 8 giờ. Mỗi ngày bạn nhận 10.000 × 0,015% × 3 = 4,5 USDT, khoảng 135 USDT trong 30 ngày. Phí mở và đóng bốn lệnh ở 0,05% là khoảng 20 USDT, lợi nhuận ròng khoảng 115 USDT trên 20.000 USDT vốn."],"mistakes":["Dùng đòn bẩy cao cho chân short, khiến nó bị thanh lý khi giá tăng vọt.","Chỉ nhìn funding của một kỳ rồi nhân lên cả năm.","Quên tính phí bốn lệnh và spread vào lợi nhuận."],"faq":[{"q":"Arbitrage funding rate có rủi ro không?","a":"Có. Funding có thể đổi dấu, chân short có thể bị thanh lý nếu ký quỹ không đủ, và còn rủi ro sàn hoặc stablecoin."},{"q":"Lợi nhuận arbitrage funding được tính thế nào?","a":"Bằng tổng funding nhận được trừ phí giao dịch và các chi phí khác, chia cho tổng vốn của cả hai chân, không chỉ vốn ký quỹ."}],"title":"Arbitrage funding rate là gì? Chiến lược ăn funding","description":"Arbitrage funding rate là gì, cách mua spot và short perp để thu funding, cách tính lợi nhuận ròng và các rủi ro chính.","related":[["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["arbitrage","Arbitrage (Kinh doanh chênh lệch giá)","Arbitrage là chiến lược kiếm lời từ chênh lệch giá của cùng một tài sản giữa hai thị trường, bằng cách mua ở nơi rẻ và bán ở nơi đắt gần như cùng lúc."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Giá đi ngang, số dư giảm? Vượt qua ải cuối với bài toán chi phí"},"coin":null,"tool":"/funding-rates","cta":false},"hardware-wallet":{"slug":"hardware-wallet","cat":"wallets-security","en":"Hardware wallet","contentLocale":"vi","term":"Ví cứng (Hardware wallet)","aka":["hardware wallet","ví phần cứng"],"short":"Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại.","body":[["Ví cứng như Ledger, Trezor hay Keystone tạo ",["khóa riêng tư","private-key"]," bên trong chip bảo mật. Khi bạn gửi tiền, ứng dụng trên máy tính chỉ chuẩn bị giao dịch; thiết bị hiển thị địa chỉ và số tiền, bạn bấm nút ",["xác nhận","block-confirmations"]," thì chữ ký mới được tạo."],["Màn hình trên thiết bị là điểm quan trọng nhất: nếu mã độc thay địa chỉ trên máy tính, bạn vẫn thấy địa chỉ thật trên ví cứng để so sánh. Tài sản không nằm trong thiết bị mà nằm trên ",["blockchain","blockchain"],", thiết bị chỉ giữ khóa."],["Nếu ví cứng bị mất hoặc hỏng, bạn mua thiết bị mới và khôi phục bằng ",["cụm từ khôi phục","seed-phrase"],". Vì vậy bản sao lưu cụm từ quan trọng ngang chính thiết bị."]],"example":["Giả sử bạn rút 3 ",["ETH","ethereum"]," từ sàn về ví cứng. Trên máy tính, ",["địa chỉ nhận","wallet-address"]," hiển thị là 0x7a3f…91c2. Bạn kiểm tra trên màn hình ví cứng, thấy đúng 0x7a3f…91c2 nên mới dán vào sàn. Ba tháng sau thiết bị rơi vỡ; bạn mua chiếc mới với giá khoảng 80 USD, nhập 24 từ khôi phục và thấy lại đủ 3 ETH ở cùng địa chỉ."],"mistakes":["Mua ví cứng từ người bán không chính hãng hoặc nhận thiết bị kèm sẵn tờ giấy ghi cụm từ khôi phục.","Nhập cụm từ khôi phục vào máy tính hoặc trang web khi có ai đó yêu cầu “xác minh” hay “cập nhật”.","Bấm xác nhận trên thiết bị mà không đọc địa chỉ và số tiền hiển thị trên màn hình."],"faq":[{"q":"Mất ví cứng thì có mất tiền không?","a":"Không, nếu bạn còn cụm từ khôi phục. Bạn chỉ cần khôi phục trên thiết bị mới hoặc ví tương thích."},{"q":"Ví cứng có cần kết nối internet không?","a":"Thiết bị không cần internet. Nó kết nối với máy tính hoặc điện thoại qua cáp, Bluetooth hay mã QR, và ứng dụng trên đó mới là thứ phát giao dịch lên mạng."}],"title":"Ví cứng (hardware wallet) là gì? Cách hoạt động","description":"Ví cứng là gì, cách nó ký giao dịch ngoại tuyến, mất thiết bị thì sao và các lỗi cần tránh khi mua, dùng ví cứng.","related":[["cold-wallet","Ví lạnh (Cold wallet)","Ví lạnh là cách lưu khóa riêng tư hoàn toàn ngoại tuyến, ví dụ trên ví cứng hoặc thiết bị không bao giờ kết nối mạng, để giảm tối đa rủi ro bị hack từ xa."],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."],["private-key","Khóa riêng tư (Private key)","Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi."],["address-poisoning","Đầu độc địa chỉ (Address poisoning)","Đầu độc địa chỉ là chiêu lừa đảo gửi giao dịch nhỏ từ một địa chỉ có đầu và cuối giống địa chỉ bạn hay dùng, để bạn sao chép nhầm từ lịch sử giao dịch và chuyển tiền cho kẻ gian."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"governance-token":{"slug":"governance-token","cat":"defi","en":"Governance token","contentLocale":"vi","term":"Token quản trị (Governance token)","aka":["governance token","token governance","token bỏ phiếu"],"short":"Token quản trị là token cho người nắm giữ quyền đề xuất và bỏ phiếu về các thay đổi của một giao thức hay DAO, ví dụ UNI của Uniswap hay AAVE của Aave.","body":["Mỗi token thường tương ứng một phiếu, và bạn có thể ủy quyền phiếu cho người khác mà không chuyển token. Các vấn đề hay được bỏ phiếu gồm bật tắt phí giao thức, thêm tài sản mới, chỉnh thông số rủi ro, phân bổ kho bạc và nâng cấp hợp đồng.",["Giá trị kinh tế của token quản trị không phải lúc nào cũng rõ ràng. Nhiều token chỉ có quyền bỏ phiếu mà không được chia doanh thu. Giá token phụ thuộc vào kỳ vọng, nhu cầu thị trường và lịch ",["mở khóa token","token-unlock"]," của đội ngũ, nhà đầu tư."],["Token quản trị thường được phân phối qua ",["airdrop","airdrop"]," cho người dùng sớm, phần thưởng ",["thanh khoản","liquidity"]," và phân bổ cho đội ngũ. Khi xem ",["tokenomics","tokenomics"],", hãy chú ý phần trăm do đội ngũ và quỹ nắm giữ, vì đó cũng là mức kiểm soát phiếu bầu."]],"example":"Giả sử một giao thức có tổng cung 1 tỷ token quản trị: 40% cho cộng đồng, 30% cho đội ngũ, 20% cho nhà đầu tư, 10% cho kho bạc. Bạn có 5.000 token, tức 0,0005% phiếu. Đội ngũ và nhà đầu tư cùng nắm 500 triệu token, đủ chi phối nếu cùng bỏ phiếu. Nếu sắp mở khóa thêm 100 triệu token cho nhà đầu tư, áp lực bán có thể tăng.","mistakes":["Mua token quản trị vì nghĩ chắc chắn được chia lợi nhuận giao thức.","Bỏ qua lịch mở khóa token của đội ngũ và nhà đầu tư.","Ủy quyền phiếu cho địa chỉ lạ qua trang không chính thức, lẫn với yêu cầu cấp quyền token."],"faq":[{"q":"Token quản trị có giá trị gì?","a":"Giá trị đến từ quyền bỏ phiếu và kỳ vọng thị trường, đôi khi kèm quyền lợi kinh tế nếu DAO bỏ phiếu chia phí. Mỗi dự án thiết kế khác nhau."},{"q":"Có cần khóa token để bỏ phiếu không?","a":"Tùy giao thức. Một số chỉ cần nắm và ủy quyền, số khác yêu cầu khóa token một thời gian để có phiếu bầu."}],"title":"Token quản trị là gì? Quyền bỏ phiếu trong DeFi","description":"Token quản trị (governance token) là gì, quyền bỏ phiếu hoạt động ra sao, giá trị đến từ đâu và cần xem gì trong tokenomics.","related":[["dao","DAO (Tổ chức tự trị phi tập trung)","DAO là tổ chức tự trị phi tập trung, nơi quy tắc và quỹ chung được quản lý bằng hợp đồng thông minh, còn các quyết định được thành viên bỏ phiếu, thường bằng token quản trị."],["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó."],["airdrop","Airdrop","Airdrop là việc một dự án phát token miễn phí vào ví của người dùng đủ điều kiện, thường để thưởng người dùng sớm, phân phối token rộng hơn hoặc quảng bá dự án."],["coin-vs-token","Coin và token (Coin vs token)","Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"usdt":{"slug":"usdt","cat":"stablecoins","en":"USDT (Tether)","contentLocale":"vi","term":"USDT (Tether)","aka":["Tether","USDT","đô la Tether"],"short":"USDT là stablecoin do công ty Tether phát hành, neo theo tỷ lệ 1 USDT bằng 1 USD và là đồng ổn định được giao dịch nhiều nhất trên các sàn crypto.","body":[["Tether tuyên bố mỗi USDT được đảm bảo bằng dự trữ, chủ yếu là tín phiếu kho bạc Mỹ, tiền gửi và một số tài sản khác, và công bố báo cáo ",["xác nhận","block-confirmations"]," định kỳ. Khách hàng đủ điều kiện có thể phát hành hoặc đổi USDT trực tiếp với Tether, còn người dùng phổ thông mua bán qua sàn hoặc ",["P2P","p2p-trading"],"."],["USDT có mặt trên nhiều ",["blockchain","blockchain"],": Tron (TRC20), ",["Ethereum","ethereum"]," (ERC20), BNB Chain, Solana, TON và các mạng khác. USDT trên Tron được dùng nhiều để chuyển tiền vì phí thấp. Khi nạp rút, bạn phải chọn đúng mạng mà bên nhận hỗ trợ."],["Tether có thể đóng băng USDT tại các địa chỉ liên quan đến hoạt động phạm pháp theo yêu cầu của cơ quan chức năng. Tại EU, USDT không được xem là tuân thủ ",["MiCA","mica"],", nên nhiều sàn đã hạn chế cặp USDT cho người dùng EU."]],"example":["Giả sử bạn mua 500 USDT qua P2P với tỷ giá giả định 25.500 VND mỗi USDT, tổng 12.750.000 VND. Bạn chuyển 500 USDT sang sàn khác qua mạng TRC20, ",["phí rút","withdrawal-fee"]," ví dụ 1 USDT, sàn kia nhận 499 USDT. Nếu chọn mạng ERC20 với phí ví dụ 5 USDT, bạn chỉ nhận 495 USDT. Số USDT tính ra VND vẫn thay đổi theo tỷ giá P2P."],"mistakes":["Gửi USDT TRC20 vào địa chỉ chỉ hỗ trợ ERC20 hoặc ngược lại.","Mua USDT P2P và chuyển khoản cho người khác ngoài tên của người bán trên quảng cáo.","Tin rằng USDT luôn đổi được đúng 1 USD trên mọi sàn và mọi thời điểm."],"faq":[{"q":"USDT có phải là đô la thật không?","a":"Không. USDT là token do Tether phát hành, được thiết kế để giữ giá 1 USD nhờ dự trữ. Giá thị trường thường rất sát 1 USD nhưng có thể lệch nhẹ."},{"q":"Nên chọn mạng nào khi chuyển USDT?","a":"Chọn mạng mà cả bên gửi và bên nhận đều hỗ trợ, sau đó so phí rút. TRC20 và các mạng phí thấp thường rẻ hơn ERC20."}],"title":"USDT là gì? Tether hoạt động thế nào","description":"USDT (Tether) là gì, được đảm bảo ra sao, USDT trên các mạng TRC20, ERC20, BEP20 khác nhau thế nào và lưu ý khi mua P2P.","related":[["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["usdc","USDC (USD Coin)","USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền."],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."],["p2p-trading","Giao dịch P2P (C2C)","Giao dịch P2P là hình thức mua bán crypto trực tiếp giữa hai người dùng trên một nền tảng, trong đó sàn giữ coin của người bán làm bảo đảm cho tới khi người mua thanh toán xong."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"synthetic-dollar":{"slug":"synthetic-dollar","cat":"stablecoins","en":"Synthetic dollar (delta-neutral stablecoin)","contentLocale":"vi","term":"Đô la tổng hợp (stablecoin delta trung tính)","aka":["synthetic dollar","stablecoin delta neutral","đô la tổng hợp"],"short":"Đô la tổng hợp là token giữ giá quanh 1 USD bằng cách nắm giữ crypto đồng thời mở vị thế short tương ứng trên hợp đồng vĩnh cửu, để lãi lỗ hai bên triệt tiêu nhau.","body":[["Ví dụ nổi bật là USDe của Ethena. Giao thức nhận tài sản như ",["ETH","ethereum"]," hoặc ",["BTC","bitcoin"],", rồi mở ",["vị thế short","long-and-short"]," cùng giá trị trên các sàn phái sinh. Khi giá ETH tăng, phần spot lời còn vị thế short lỗ, và ngược lại. Tổng giá trị nhờ vậy gần như cố định theo USD, gọi là trạng thái delta trung tính."],["Lợi suất của loại token này đến chủ yếu từ ",["funding rate","funding-rate"]," mà phe long trả cho phe short, cộng với phần thưởng ",["staking","staking"]," nếu tài sản là token staking. Khi thị trường hưng phấn, funding dương cao và lợi suất hấp dẫn."],["Rủi ro nằm ở chỗ funding có thể âm kéo dài, khi đó giao thức phải trả tiền thay vì nhận. Ngoài ra còn rủi ro sàn phái sinh gặp sự cố, rủi ro ",["thanh khoản","liquidity"]," khi nhiều người rút cùng lúc và rủi ro token staking lệch giá."]],"example":"Giả sử giao thức nhận 100 ETH khi ETH giá 3.000 USD và mở short 100 ETH. Tổng giá trị là 300.000 USD. Nếu ETH tăng lên 3.300 USD, phần spot lời 30.000 USD, short lỗ 30.000 USD, tổng vẫn 300.000 USD. Nếu funding là 0,01% mỗi 8 giờ, phe short nhận khoảng 30 USD mỗi kỳ trên vị thế 300.000 USD, tức khoảng 90 USD mỗi ngày. Nếu funding chuyển sang âm 0,01%, con số đó thành khoản phải trả.","mistakes":["Nghĩ lợi suất của đô la tổng hợp là cố định như lãi tiết kiệm, trong khi nó phụ thuộc trực tiếp vào funding rate.","Bỏ qua rủi ro đối tác ở các sàn đang giữ vị thế short.","Gộp chung đô la tổng hợp với stablecoin có dự trữ tiền mặt và trái phiếu."],"faq":[{"q":"USDe có phải stablecoin không?","a":"USDe thường được gọi là đô la tổng hợp. Nó giữ giá bằng chiến lược phòng hộ delta trung tính chứ không phải bằng tiền mặt gửi ngân hàng, nên rủi ro khác với USDT hay USDC."},{"q":"Funding âm ảnh hưởng gì đến đô la tổng hợp?","a":"Khi funding âm, vị thế short phải trả phí thay vì nhận. Lợi suất giảm và nếu kéo dài, giao thức phải dùng quỹ dự phòng để bù."}],"title":"Đô la tổng hợp là gì? Stablecoin delta trung tính","description":"Đô la tổng hợp như USDe giữ giá bằng spot cộng short perpetual. Tìm hiểu nguồn lợi suất, funding rate và các rủi ro chính.","related":[["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."]],"lesson":null,"coin":{"slug":"ethena-usde","name":"Ethena USDe","symbol":"USDE"},"tool":"/funding-rates","cta":false}});
